140	  child: boolean; female: boolean;
141	  height: number;        // m, ở tỉ lệ 1
142	  geometry: THREE.BufferGeometry;           // position (Float32 ×3), normal (×3), uv (×2, toạ độ trong atlas), aBones (Uint8 ×2), aW (Float32 ×1: trọng số xương thứ nhất), có index
143	  hat: THREE.BufferGeometry | null;         // cùng bộ attribute, thêm nón lá; null với trẻ em
144	  clips: Record<CrowdClipName, CrowdClip>;
145	}
146	export interface CrowdParsed { chars: CrowdChar[]; bones: number; animWidth: number; animHeight: number; animData: Uint16Array; maxVerts: number; maxIndices: number }   // animData: RGBA half-float, mỗi hàng một khung, 3 texel mỗi xương
147	export interface CrowdData extends CrowdParsed { anim: THREE.DataTexture; atlas: THREE.Texture }
148	
149	const MAGIC = 'DNCR', VERSION = 1;
150	const CLIP_NAMES: CrowdClipName[] = ['walk', 'jog', 'idle', 'photo'];
151	
152	/* ===== Đọc tệp (thuần: không DOM, không fetch; chạy được trong node) ===== */
153	export function crowdParse(buf: ArrayBuffer): CrowdParsed {
154	  if (buf.byteLength < 12) throw new Error('crowd.bin: tệp quá ngắn');
155	  const head = new Uint8Array(buf, 0, 4), dv = new DataView(buf);
156	  if (String.fromCharCode(...head) !== MAGIC) throw new Error('crowd.bin: sai magic');
157	  const ver = dv.getUint32(4, true); if (ver !== VERSION) throw new Error(`crowd.bin: phiên bản ${ver} (cần ${VERSION})`);
158	  const J = dv.getUint32(8, true); if (12 + J > buf.byteLength || J % 4) throw new Error('crowd.bin: phần JSON hỏng');
159	  const meta = JSON.parse(new TextDecoder().decode(new Uint8Array(buf, 12, J)));
160	  const base = 12 + J;
161	  const view = <T>(C: { new (b: ArrayBuffer, o: number, n: number): T; BYTES_PER_ELEMENT: number }, off: number, n: number): T => {
162	    if (off % C.BYTES_PER_ELEMENT || base + off + n * C.BYTES_PER_ELEMENT > buf.byteLength) throw new Error('crowd.bin: mảng vượt tệp');
163	    return new C(buf, base + off, n);
164	  };
165	  const bones: number = meta.bones;
166	  let maxVerts = 0, maxIndices = 0;
167	  const chars: CrowdChar[] = meta.chars.map((c) => {
168	    const nv = c.verts + c.hatVerts, ni = (c.tris + c.hatTris) * 3;
169	    const pos = view(Float32Array, c.pos, nv * 3), nrm = view(Float32Array, c.nrm, nv * 3), uv = view(Float32Array, c.uv, nv * 2);
170	    const bi = view(Uint8Array, c.bones, nv * 2), w = view(Float32Array, c.w, nv), idx = view(Uint16Array, c.idx, ni);
171	    const geo = (v: number, i: number): THREE.BufferGeometry => {
172	      const g = new THREE.BufferGeometry();
173	      g.setAttribute('position', new THREE.BufferAttribute(pos.subarray(0, v * 3), 3));
174	      g.setAttribute('normal', new THREE.BufferAttribute(nrm.subarray(0, v * 3), 3));
175	      g.setAttribute('uv', new THREE.BufferAttribute(uv.subarray(0, v * 2), 2));
176	      g.setAttribute('aBones', new THREE.BufferAttribute(bi.subarray(0, v * 2), 2));
177	      g.setAttribute('aW', new THREE.BufferAttribute(w.subarray(0, v), 1));
178	      g.setIndex(new THREE.BufferAttribute(idx.subarray(0, i), 1));
179	      g.computeBoundingBox(); g.computeBoundingSphere();
180	      maxVerts = Math.max(maxVerts, v); maxIndices = Math.max(maxIndices, i);
181	      return g;
182	    };
183	    const clips = {} as Record<CrowdClipName, CrowdClip>;
184	    for (const n of CLIP_NAMES) {
185	      const k = c.clips?.[n]; if (!k) throw new Error(`crowd.bin: ${c.id} thiếu đoạn ${n}`);
186	      clips[n] = { row: k.row, frames: k.frames, fps: k.fps, loop: !!k.loop, speed: k.speed };
187	    }
188	    return { id: c.id, child: !!c.child, female: !!c.female, height: c.height, geometry: geo(c.verts, c.tris * 3), hat: c.hatVerts > 0 ? geo(nv, ni) : null, clips };
189	  });
190	  const a = meta.anim;
191	  if (a.width !== bones * 3 || a.bytes !== a.width * a.height * 8) throw new Error('crowd.bin: kích thước texture chuyển động sai');
192	  const animData = view(Uint16Array, a.offset, a.width * a.height * 4);
193	  return { chars, bones, animWidth: a.width, animHeight: a.height, animData, maxVerts, maxIndices };
194	}
195	
196	/* ===== Tải trong trình duyệt ===== */
197	let loaded: CrowdData | null = null;
198	let pending: Promise<CrowdData | null> | null = null;
199	
200	// Kết quả của lần crowdLoad đã xong (null nếu chưa xong, lỗi, hoặc ?crowd=off)
201	export function crowdGet(): CrowdData | null { return loaded; }
202	
203	// Tải bin + jpg theo BASE_URL, tối đa CONFIG.people.crowd.loadTimeoutMs; lỗi bất kỳ → console.warn một lần, trả null.
204	// ?crowd=off → null ngay, không gửi yêu cầu nào. Gọi nhiều lần dùng chung một lượt tải.
205	export function crowdLoad(): Promise<CrowdData | null> {
206	  if (pending) return pending;
207	  if (typeof location !== 'undefined' && new URLSearchParams(location.search).get('crowd') === 'off') return (pending = Promise.resolve(null));
208	  pending = (async () => {
209	    const C = CONFIG.people.crowd, ctl = new AbortController();
210	    let timer: ReturnType<typeof setTimeout> | undefined;
211	    const timeout = new Promise<never>((_, rej) => { timer = setTimeout(() => { ctl.abort(); rej(new Error(`quá ${C.loadTimeoutMs} ms`)); }, C.loadTimeoutMs); });
212	    const work = (async (): Promise<CrowdData> => {
213	      const base = import.meta.env.BASE_URL;
214	      const [rb, ri] = await Promise.all([fetch(base + C.bin, { signal: ctl.signal }), fetch(base + C.atlas, { signal: ctl.signal })]);
215	      if (!rb.ok || !ri.ok) throw new Error(`HTTP ${rb.status} / ${ri.status}`);
216	      const [buf, blob] = await Promise.all([rb.arrayBuffer(), ri.blob()]);
217	      const parsed = crowdParse(buf);
218	      const bmp = await createImageBitmap(blob);
219	      const atlas = new THREE.Texture(bmp);
220	      atlas.flipY = false; atlas.colorSpace = THREE.SRGBColorSpace; atlas.name = 'peopleCrowdAtlas'; atlas.needsUpdate = true;
221	      const anim = new THREE.DataTexture(parsed.animData as Uint16Array<ArrayBuffer>, parsed.animWidth, parsed.animHeight, THREE.RGBAFormat, THREE.HalfFloatType);
222	      anim.minFilter = anim.magFilter = THREE.NearestFilter; anim.generateMipmaps = false; anim.name = 'peopleCrowdAnim'; anim.needsUpdate = true;
223	      return { ...parsed, anim, atlas };
224	    })();
225	    work.catch(() => {}); timeout.catch(() => {});
226	    try {
227	      loaded = await Promise.race([work, timeout]);
228	    } catch (e) {
229	      console.warn('[people] không dùng được đám đông người thật, dùng hình khối:', e instanceof Error ? e.message : e);
230	      loaded = null;
231	    } finally { clearTimeout(timer); }
232	    return loaded;
233	  })();
234	  return pending;
235	}
236	import * as THREE from 'three';
237	import { CONFIG } from '../../config';
238	import { shared } from '../../core/shared';
239	import { PP_FLAG } from './kinds';
240	import type { CrowdData, CrowdClip, CrowdClipName } from './crowdData';
241	import type { Walker } from '../people';
242	
243	/* =====================================================================
244	   ĐÁM ĐÔNG NGƯỜI THẬT (D-032) — mỗi hệ người đi bộ một THREE.BatchedMesh (r165, WEBGL_multi_draw ⇒ 1 lệnh vẽ), một id mỗi người.
245	   Spec: docs/superpowers/specs/2026-11-12-dam-dong-nguoi-that-design.md §4, §5. Dữ liệu: crowdData.ts (định dạng crowd.bin ở đầu file đó).
246	   - Skin trong vertex shader: 2 xương mỗi đỉnh (aBones, aW), ma trận 3×4 của xương đọc từ texture chuyển động (uCrowdAnim, texelFetch),
247	     nội suy hai khung liền nhau; đoạn lặp thì khung cuối nội suy về khung đầu, đoạn không lặp (photo) giữ khung cuối.
248	   - Thông số từng người (hàng đầu đoạn, ±số khung, khung/giây, pha theo khung) nằm trong một DataTexture float dùng chung cho cả 3 hệ
249	     (uCrowdPeople). Chỉ số của người trong texture đó (= chỗ bắt đầu của hệ + id) ghi vào kênh alpha của batchingColorTexture
250	     (setColorAt chỉ ghi rgb; rgb = hệ số sáng theo người, spec §4.11). Một vật liệu cho cả 3 hệ ⇒ không có uniform riêng theo hệ.
251	   - Thời gian: shared.uTime; lấy mod theo chu kỳ của người TRƯỚC khi nhân khung/giây để pha không mất chính xác khi trang chạy lâu.
252	   - Phải setColorAt cho mọi id (r165: thiếu bảng màu thì renderer tra lại program mỗi khung). sortObjects = false; không setInstanceCountAt.
253	   - Ẩn người: setVisibleAt (tự đặt _visibilityChanged). setMatrixAt tự đặt matricesTexture.needsUpdate.
254	   - Khối cầu bao từng id: của lưới nguồn, nới cullPad / tỉ lệ người (đơn vị cục bộ; matrix nhân lại tỉ lệ) để tay chân không bị cắt nhầm.
255	   ===================================================================== */
256	const PEOPLE_W = 32, PEOPLE_H = 32;   // texel — sức chứa texture thông số: 1 024 người cho mọi hệ (hiện 226)
257	
258	/* ---------- băm theo chỉ số (không dùng rand / rnd / rng) ---------- */
259	const crHashStr = (s: string): number => { let h = 2166136261; for (let k = 0; k < s.length; k++) h = Math.imul(h ^ s.charCodeAt(k), 16777619); return h >>> 0; };
260	const crHash = (a: number, b: number): number => {
261	  let h = Math.imul(a ^ Math.imul((b + 0x9e3779b9) | 0, 0x85ebca6b), 0xc2b2ae35);
262	  h ^= h >>> 16; h = Math.imul(h, 0x7feb352d); h ^= h >>> 15; h = Math.imul(h, 0x846ca68b); h ^= h >>> 16;
263	  return (h >>> 0) / 4294967296;
264	};
265	
266	/* Dùng được người thật không: có dữ liệu và có WEBGL_multi_draw (thiếu thì r165 vẽ mỗi người một lệnh ⇒ lùi về hình khối) */
267	export function crowdUsable(data: CrowdData | null, hasMultiDraw: boolean): boolean {
268	  return !!data && hasMultiDraw && data.chars.some((c) => c.child) && data.chars.some((c) => !c.child);
269	}
270	
271	/* Chọn nhân vật cho người i của hệ system (tất định). isChild → chỉ nhân vật trẻ em; avoid: nhân vật của người đi cùng (−1 nếu không), tránh trùng khi có ≥ 2 lựa chọn */
272	export function crowdPick(chars: { child: boolean }[], system: string, i: number, isChild: boolean, avoid: number): number {
273	  let cand: number[] = [];
274	  chars.forEach((c, k) => { if (c.child === isChild) cand.push(k); });
275	  if (!cand.length) cand = chars.map((_, k) => k);
276	  let k = Math.floor(crHash(crHashStr(system), i) * cand.length);
277	  if (cand[k] === avoid && cand.length > 1) k = (k + 1) % cand.length;
278	  return cand[k];
279	}
280	
281	/* Nhịp phát chuyển động = tốc độ người ÷ (tốc độ tự nhiên của đoạn × tỉ lệ người), kẹp [rateMin, rateMax] (spec §4.5). natural = 0 (đứng) → 1 */
282	export function crowdRate(speed: number, natural: number, scale: number): number {
283	  const C = CONFIG.people.crowd;
284	  if (!(natural > 0)) return 1;
285	  return Math.min(C.rateMax, Math.max(C.rateMin, speed / (natural * scale)));
286	}
287	
288	/* Khung (số thực) trong [0, frames) tại thời điểm t (s); phase: pha chu kỳ, rad (Walker.phase). Bản CPU của công thức trong shader (VS_SKIN) */
289	export function crowdFrame(t: number, clip: CrowdClip, rate: number, phase: number): number {
290	  const N = clip.frames;
291	  if (!clip.loop) return N - 1;
292	  const fr = clip.fps * rate, T = N / fr, ph = crPhase(phase, N);
293	  const f = ((t % T) * fr + ph) % N;
294	  return f < 0 ? f + N : f;
295	}
296	const crPhase = (phase: number, N: number) => ((((phase / (2 * Math.PI)) % 1) + 1) % 1) * N;   // rad → khung, [0, N)
297	const crClip = (w: Walker): CrowdClipName => (w.kind === 'run' ? 'jog' : w.kind === 'stand' ? ((w.flags ?? 0) & PP_FLAG.photo ? 'photo' : 'idle') : 'walk');
298	
299	/* ---------- shader ---------- */
300	const VS_PARS = /* glsl */`#include <batching_pars_vertex>
301	uniform highp sampler2D uCrowdAnim;
302	uniform highp sampler2D uCrowdPeople;
303	uniform float uTime;
304	attribute vec2 aBones;
305	attribute float aW;
306	vec4 crRow( int c, int f0, int f1, float t ) { return mix( texelFetch( uCrowdAnim, ivec2( c, f0 ), 0 ), texelFetch( uCrowdAnim, ivec2( c, f1 ), 0 ), t ); }
307	`;
308	// thay beginnormal_vertex: tính 3 hàng ma trận skin (crR0..2) một lần, dùng lại ở begin_vertex
309	const VS_SKIN = /* glsl */`
310	vec4 crR0 = vec4( 1.0, 0.0, 0.0, 0.0 ), crR1 = vec4( 0.0, 1.0, 0.0, 0.0 ), crR2 = vec4( 0.0, 0.0, 1.0, 0.0 );
311	#if defined( USE_BATCHING ) && defined( USE_BATCHING_COLOR )
312	{
313	  int crCs = textureSize( batchingColorTexture, 0 ).x, crId = int( batchId );
314	  int crG = int( texelFetch( batchingColorTexture, ivec2( crId % crCs, crId / crCs ), 0 ).a + 0.5 );   // chỉ số người trong uCrowdPeople
315	  int crPw = textureSize( uCrowdPeople, 0 ).x;
316	  vec4 crP = texelFetch( uCrowdPeople, ivec2( crG % crPw, crG / crPw ), 0 );   // x hàng đầu đoạn, y ±số khung (âm: giữ khung cuối), z khung/giây, w pha (khung)
317	  int crN = int( abs( crP.y ) + 0.5 ), f0 = crN - 1, f1 = crN - 1; float ft = 0.0;
318	  if ( crP.y > 0.0 ) {
319	    float crF = mod( mod( uTime, crP.y / crP.z ) * crP.z + crP.w, crP.y );   // mod theo chu kỳ trước: uTime lớn không làm mất chính xác pha
320	    f0 = min( int( crF ), crN - 1 ); f1 = f0 + 1 >= crN ? 0 : f0 + 1; ft = fract( crF );
321	  }
322	  int crRw = int( crP.x + 0.5 ); f0 += crRw; f1 += crRw;
323	  int b0 = int( aBones.x + 0.5 ) * 3, b1 = int( aBones.y + 0.5 ) * 3; float w1 = 1.0 - aW;
324	  crR0 = crRow( b0, f0, f1, ft ) * aW + crRow( b1, f0, f1, ft ) * w1;
325	  crR1 = crRow( b0 + 1, f0, f1, ft ) * aW + crRow( b1 + 1, f0, f1, ft ) * w1;
326	  crR2 = crRow( b0 + 2, f0, f1, ft ) * aW + crRow( b1 + 2, f0, f1, ft ) * w1;
327	}
328	#endif
329	vec3 objectNormal = vec3( dot( crR0.xyz, normal ), dot( crR1.xyz, normal ), dot( crR2.xyz, normal ) );
330	#ifdef USE_TANGENT
331	vec3 objectTangent = vec3( tangent.xyz );
332	#endif
333	`;
334	const VS_POS = /* glsl */`vec4 crPos = vec4( position, 1.0 );
335	vec3 transformed = vec3( dot( crR0, crPos ), dot( crR1, crPos ), dot( crR2, crPos ) );
336	#ifdef USE_ALPHAHASH
337	vPosition = vec3( position );
338	#endif
339	`;
340	
341	type CrowdState = { people: THREE.DataTexture; next: number };
342	const mats = new WeakMap<CrowdData, THREE.MeshStandardMaterial>();
343	/* Một vật liệu dùng chung cho 3 hệ (theo bộ dữ liệu). Texture trong uniform (uCrowdAnim, uCrowdPeople) không được prewarm tải trước:
344	   bên dựng gọi renderer.initTexture (people.ts) */
345	export function crowdMaterial(data: CrowdData): THREE.MeshStandardMaterial {
346	  const old = mats.get(data); if (old) return old;
347	  const m = new THREE.MeshStandardMaterial({ map: data.atlas, roughness: CONFIG.people.roughness, metalness: 0 });
348	  m.name = 'peopleCrowd';
349	  const people = new THREE.DataTexture(new Float32Array(PEOPLE_W * PEOPLE_H * 4), PEOPLE_W, PEOPLE_H, THREE.RGBAFormat, THREE.FloatType);
350	  people.minFilter = people.magFilter = THREE.NearestFilter; people.generateMipmaps = false; people.name = 'peopleCrowdParams'; people.needsUpdate = true;
351	  const state: CrowdState = { people, next: 0 };
352	  m.userData.crowd = state;
353	  m.onBeforeCompile = (s) => {
354	    s.uniforms.uTime = shared.uTime; s.uniforms.uCrowdAnim = { value: data.anim }; s.uniforms.uCrowdPeople = { value: people };
355	    s.vertexShader = s.vertexShader.replace('#include <batching_pars_vertex>', VS_PARS).replace('#include <beginnormal_vertex>', VS_SKIN).replace('#include <begin_vertex>', VS_POS);
356	    m.userData.vs = s.vertexShader;
357	  };
358	  m.customProgramCacheKey = () => 'peopleCrowd';
359	  mats.set(data, m);
360	  return m;
361	}
362	/* Texture thông số theo người của vật liệu (cho renderer.initTexture) */
363	export const crowdParams = (m: THREE.Material): THREE.DataTexture => (m.userData.crowd as CrowdState).people;
364	
365	/* Thông tin theo id (móc kiểm thử, stepPeople): nhân vật, có nón, tỉ lệ người (m/m so với lưới), tổng tam giác */
366	export interface CrowdInfo { char: Int16Array; hat: Uint8Array; scale: Float32Array; tris: number }
367	
368	/* Dựng một hệ: một id mỗi người theo thứ tự list. Tỉ lệ người lớn = heightScale × Walker.scale; trẻ em (Walker.scale = childScale) = heightScale
369	   (nhân vật trẻ em đã thấp sẵn, spec §4.10). Cờ nón + nhân vật có bản nón → lưới hat. Không gọi rnd() / rand() / rng */
370	export function crowdBuild(data: CrowdData, list: Walker[], system: string): THREE.BatchedMesh {
371	  const P = CONFIG.people, C = P.crowd, mat = crowdMaterial(data), st = mat.userData.crowd as CrowdState, n = list.length;
372	  if (st.next + n > PEOPLE_W * PEOPLE_H) throw new Error('crowd: hết chỗ trong texture thông số người');
373	  const char = new Int16Array(n), hat = new Uint8Array(n), scale = new Float32Array(n), geos: THREE.BufferGeometry[] = [];
374	  let nv = 0, ni = 0;
375	  list.forEach((w, i) => {
376	    const child = w.scale === P.childScale, lead = w.follow ?? -1;
377	    char[i] = crowdPick(data.chars, system, i, child, lead >= 0 && lead < i ? char[lead] : -1);
378	    const ch = data.chars[char[i]], useHat = !!((w.flags ?? 0) & PP_FLAG.hat) && !!ch.hat, src = useHat ? ch.hat : ch.geometry;
379	    hat[i] = useHat ? 1 : 0;
380	    scale[i] = C.heightScale * (child ? 1 : (w.scale ?? 1));
381	    // vỏ dùng chung attribute của lưới nguồn (addGeometry chép dữ liệu), chỉ khác khối cầu bao đã nới
382	    const g = new THREE.BufferGeometry();
383	    for (const k of Object.keys(src.attributes)) g.setAttribute(k, src.attributes[k]);
384	    g.setIndex(src.index); g.boundingBox = src.boundingBox;
385	    g.boundingSphere = src.boundingSphere.clone(); g.boundingSphere.radius += C.cullPad / scale[i];
386	    geos.push(g); nv += src.getAttribute('position').count; ni += src.index.count;
387	  });
388	  const mesh = new THREE.BatchedMesh(n, nv, ni, mat), col = new THREE.Color(), pd = st.people.image.data as unknown as Float32Array, base = st.next, sysH = crHashStr(system) ^ 0x5bd1e995;
389	  st.next += n;
390	  geos.forEach((g, i) => {
391	    const id = mesh.addGeometry(g), w = list[i], name = crClip(w), clip = data.chars[char[i]].clips[name];
392	    mesh.setColorAt(id, col.setScalar(C.tint[0] + (C.tint[1] - C.tint[0]) * crHash(sysH, i)));   // hệ số sáng theo người (spec §4.11); bắt buộc cho mọi id
393	    const rate = name === 'walk' || name === 'jog' ? crowdRate(w.speed, clip.speed, scale[i]) : 1;
394	    pd.set([clip.row, clip.loop ? clip.frames : -clip.frames, clip.fps * rate, crPhase(w.phase ?? 0, clip.frames)], (base + id) * 4);
395	  });
396	  const colors = (mesh as unknown as { _colorsTexture: THREE.DataTexture })._colorsTexture, cd = colors.image.data as unknown as Float32Array;
397	  for (let i = 0; i < n; i++) cd[i * 4 + 3] = base + i;   // kênh alpha: chỉ số người trong uCrowdPeople
398	  colors.needsUpdate = true; st.people.needsUpdate = true;
399	  mesh.sortObjects = false; mesh.perObjectFrustumCulled = true; mesh.frustumCulled = false;   // bao cầu cả đối tượng không tự cập nhật: bên gọi đặt nếu cần (Cầu Rồng)
400	  mesh.castShadow = mesh.receiveShadow = false;
401	  mesh.userData.crowd = { char, hat, scale, tris: ni / 3 } satisfies CrowdInfo;
402	  return mesh;
403	}
