import * as THREE from 'three';
import { UP } from './geometry';
import { CONFIG } from '../config';
import { weatherFx, vanished } from '../core/shared';
import { ppBuildGeometry } from './people/shapes';
import { ppMaterial } from './people/material';
import { ppAmp, ppCadence, type PersonKind } from './people/gait';
import type { PersonInfo } from './people/kinds';
import { crowdGet } from './people/crowdData';
import { crowdUsable, crowdBuild, crowdParams, type CrowdInfo } from './people/crowd';
import { renderer } from '../core/renderer';

/* =====================================================================
   NGƯỜI ĐI BỘ — hệ dùng chung cho Trần Thị Lý, Cầu sông Hàn, Cầu Rồng (spec G5–G10).
   Mỗi hệ: 1 InstancedMesh, hình gộp ppBuildGeometry(), vật liệu ppMaterial() (tay chân vung trong vertex shader theo shared.uTime).
   CPU chỉ dời vị trí, quay hướng; dáng đi / chạy / đứng theo thuộc tính instance aVar (pha, biên độ, cờ, nhịp) và aPants (màu quần).
   Mỗi người: { x, z, lo, hi, dir, speed, profile(c) → cao độ chân, axis: 'x' | 'z' } + kiểu người (ppApplyKinds).
   Người thật (D-032, real = true): khi đã tải được dữ liệu đám đông (crowdLoad trong main.ts) và có WEBGL_multi_draw, mỗi hệ là một
   THREE.BatchedMesh (common/people/crowd.ts, 1 lệnh vẽ); ẩn người bằng setVisibleAt. Không thì đường hình khối trên giữ nguyên (đường lùi).
   ===================================================================== */
export interface Walker {
  x: number; z: number; lo: number; hi: number; dir: number; speed: number; profile: (c: number) => number; axis?: 'x' | 'z';
  kind?: PersonKind; scale?: number; flags?: number; phase?: number;
  face?: number;     // rad quanh Y, chỉ cho người đứng (0: mặt hướng +X)
  follow?: number;   // chỉ số người dẫn (người đi cùng / trẻ em), chép vị trí dọc dải của người đó
}
export interface People { list: Walker[]; mesh: THREE.InstancedMesh | THREE.BatchedMesh; group: THREE.Group; real: boolean }

/* Băm theo chỉ số → [0, 1) (không đụng chuỗi ngẫu nhiên nào) */
const ppHash = (k: number) => { const s = Math.sin(k * 12.9898 + 78.233) * 43758.5453; return s - Math.floor(s); };
/* Góc quay quanh Y để hình (mặt hướng +X) nhìn ra phía z dương (s > 0) hoặc z âm */
export const ppFaceZ = (s: number) => (s > 0 ? -Math.PI / 2 : Math.PI / 2);

/* Gộp danh sách kiểu người của nhiều đoạn (ppAssignKinds từng đoạn) thành một, dời chỉ số follow theo vị trí đoạn trong danh sách chung */
export function ppJoinKinds(...parts: PersonInfo[][]): PersonInfo[] {
  const out: PersonInfo[] = [];
  for (const p of parts) { const base = out.length; for (const k of p) out.push({ ...k, follow: k.follow >= 0 ? k.follow + base : -1 }); }
  return out;
}

/* Gán kiểu người lên danh sách đã dựng (sau khi lấy hết rnd() của cầu, trước createPeople):
   người chạy nhận tốc độ chạy; người đi cùng chép vị trí, hướng, tốc độ, dải của người dẫn rồi lệch ngang companionGap về phía trong
   (về tim cầu với người đi dọc cầu, về phía sông với người đi dọc bờ; outward = true thì lệch ra ngoài, về phía lan can — Cầu Rồng, tránh hàng cột đèn);
   người đứng do từng cầu đặt sát lan can và quay mặt (place). */
export function ppApplyKinds(list: Walker[], infos: PersonInfo[], place: (w: Walker, info: PersonInfo, i: number) => void, outward = false): void {
  const P = CONFIG.people, [r0, r1] = P.run.speed;
  infos.forEach((info, i) => {
    const w = list[i];
    w.kind = info.kind; w.scale = info.scale; w.flags = info.flags; w.phase = info.phase;
    if (info.kind === 'run') w.speed = r0 + (r1 - r0) * ppHash(i + 0.5);
    if (info.follow >= 0) {
      const L = list[info.follow], lat = L.axis === 'z' ? 'x' : 'z';
      Object.assign(w, { x: L.x, z: L.z, dir: L.dir, speed: L.speed, lo: L.lo, hi: L.hi, axis: L.axis, profile: L.profile, follow: info.follow });
      w[lat] += (outward ? 1 : -1) * Math.sign(w[lat]) * P.companionGap;
    }
    if (info.kind === 'stand') place(w, info, i);
  });
}

export function createPeople(bridge: { group: THREE.Object3D; noReflect: THREE.Object3D[] }, list: Walker[], name: string, rnd: () => number): People {
  const P = CONFIG.people, n = list.length, crowd = crowdGet(), real = crowdUsable(crowd, renderer.extensions.has('WEBGL_multi_draw'));
  let mesh: THREE.InstancedMesh | THREE.BatchedMesh;
  if (real) {
    const bm = crowdBuild(crowd, list, name);
    for (let i = 0; i < n; i++) rnd();   // màu áo không còn tác dụng với người thật, nhưng giữ đúng một rnd() mỗi người để chuỗi của cầu không đổi
    // texture trong uniform: prewarm không tải trước (nó chỉ duyệt thuộc tính vật liệu) ⇒ tự tải lên GPU lúc dựng
    renderer.initTexture(crowd.anim); renderer.initTexture(crowd.atlas); renderer.initTexture(crowdParams(bm.material as THREE.Material));
    mesh = bm;
  } else {
    const geo = ppBuildGeometry(), col = new THREE.Color();
    const aVar = new Float32Array(n * 4), aPants = new Float32Array(n * 3);
    list.forEach((p, i) => {
      const kind = p.kind ?? 'walk';
      aVar.set([p.phase ?? 0, ppAmp(kind), p.flags ?? 0, ppCadence(kind, p.speed, p.scale ?? 1)], i * 4);   // pha, biên độ hông, cờ, nhịp (khớp material.ts)
      col.setHex(P.pants[Math.floor(ppHash(i) * P.pants.length)]); aPants.set([col.r, col.g, col.b], i * 3);   // Color chuyển hex sRGB → tuyến tính
    });
    geo.setAttribute('aVar', new THREE.InstancedBufferAttribute(aVar, 4));
    geo.setAttribute('aPants', new THREE.InstancedBufferAttribute(aPants, 3));
    const im = new THREE.InstancedMesh(geo, ppMaterial(), n);
    list.forEach((_p, i) => im.setColorAt(i, col.setHex(P.shirts[Math.floor(rnd() * P.shirts.length)])));   // màu áo: đúng một rnd() mỗi người như cũ
    im.frustumCulled = false; im.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    mesh = im;
  }
  const group = new THREE.Group(); group.name = name; group.add(mesh);
  bridge.group.add(group); bridge.noReflect.push(group);
  const people: People = { list, mesh, group, real };
  group.userData.people = people;   // cho móc kiểm thử (environment/pedestrians.ts → peopleTest)
  stepPeople(people, 0, 0);   // đặt sẵn vị trí ban đầu
  return people;
}

const _pm = new THREE.Matrix4(), _pq = new THREE.Quaternion(), _pv = new THREE.Vector3(), _ps = new THREE.Vector3(), _zero = new THREE.Matrix4().makeScale(0, 0, 0);   // tạm cấp sẵn (D-018)
/* Dời người theo dải; đứng thì đứng yên; người đi cùng chép vị trí dọc dải của người dẫn.
   Đóng cầu (bão, closable): người thứ i ẩn dần theo vanished như xe (người đi cùng ẩn cùng lúc với người dẫn): hình khối thu scale 0, người thật setVisibleAt */
export function stepPeople(P: People, dt: number, _elapsed: number, closable = true) {
  const L = P.list, clear = closable ? weatherFx.clear : 0;
  const bm = P.real ? (P.mesh as THREE.BatchedMesh) : null, im = P.real ? null : (P.mesh as THREE.InstancedMesh), sc = bm ? (bm.userData.crowd as CrowdInfo).scale : null;
  for (let i = 0; i < L.length; i++) {
    const p = L[i], alongZ = p.axis === 'z', key = alongZ ? 'z' : 'x', lead = p.follow ?? -1;
    if (vanished(lead >= 0 ? lead : i, clear)) { if (bm) bm.setVisibleAt(i, false); else im.setMatrixAt(i, _zero); continue; }
    if (lead >= 0) p[key] = L[lead][key];
    else if (p.kind !== 'stand') { p[key] += p.dir * p.speed * dt; if (p[key] > p.hi) p[key] = p.lo; if (p[key] < p.lo) p[key] = p.hi; }
    const yaw = p.kind === 'stand' ? (p.face ?? 0) : alongZ ? (p.dir > 0 ? -Math.PI / 2 : Math.PI / 2) : (p.dir > 0 ? 0 : Math.PI);
    const s = sc ? sc[i] : (p.scale ?? 1);   // người thật: tỉ lệ theo chiều cao nhân vật (crowd.ts)
    _pm.compose(_pv.set(p.x, p.profile(p[key]), p.z), _pq.setFromAxisAngle(UP, yaw), _ps.set(s, s, s));
    if (bm) { bm.setVisibleAt(i, true); bm.setMatrixAt(i, _pm); } else im.setMatrixAt(i, _pm);   // setVisibleAt / setMatrixAt của BatchedMesh tự đánh dấu cập nhật
  }
  if (im) im.instanceMatrix.needsUpdate = true;
}
/* ===== Dữ liệu đám đông người thật (D-032): đọc public/people/crowd.bin + crowd.jpg ===== */
/* Spec: docs/superpowers/specs/2026-11-12-dam-dong-nguoi-that-design.md §4; sinh bằng npm run gen:crowd (scripts/people/crowd.py).
   10 nhân vật Rocketbox (MIT) giản lược ≤ 1 600 tam giác, 22 xương, 2 xương mỗi đỉnh; chuyển động nướng thành ma trận xương.
   Hệ toạ độ của lưới: mét, +Y lên, mặt hướng +X, chân y = 0, tư thế nghỉ chữ T / chữ A (cần skin mới ra dáng đi).

   Định dạng crowd.bin (little-endian), phiên bản 1:
     0   4 byte  'DNCR'
     4   u32     phiên bản (1)
     8   u32     J = số byte phần JSON (đệm dấu cách tới bội 4)
     12  J byte  JSON utf-8: { bones, boneNames, anim: { width, height, offset, bytes }, source,
                 chars: [{ id, child, female, height, verts, tris, hatVerts, hatTris, pos, nrm, uv, bones, w, idx,
                           clips: { walk|jog|idle|photo: { row, frames, fps, loop, speed } } }] }
                 pos … idx là offset byte (tính từ đầu khối nhị phân) của từng mảng.
     12+J        khối nhị phân, mỗi mảng bắt đầu ở bội 4:
                 pos f32 ×3, nrm f32 ×3, uv f32 ×2, bones u8 ×2, w f32 ×1, idx u16 ×3 mỗi tam giác.
                 Đỉnh 0..verts−1 và tam giác 0..tris−1 là người; hatVerts / hatTris nối tiếp là nón lá (index trỏ vào mảng
                 đỉnh chung, gắn cứng xương đầu: bones = [đầu, đầu], w = 1). Bản đội nón = toàn bộ mảng.
                 anim: u16 (half-float) RGBA, width = bones × 3 texel, mỗi hàng một khung; texel (b × 3 + j) = hàng j của
                 ma trận 3×4 xương b, đưa đỉnh từ tư thế nghỉ sang tư thế khung (cùng hệ toạ độ lưới):
                   p' = Σ_k w_k · (dot(T[b_k·3], p1), dot(T[b_k·3+1], p1), dot(T[b_k·3+2], p1)), p1 = (p, 1); pháp tuyến dùng .xyz.
   uv: toạ độ trong atlas crowd.jpg với v = 0 ở mép TRÊN của ảnh (texture.flipY = false, ImageBitmap không lật).
   Đoạn: walk / idle / photo 15 khung/giây, jog 30; loop = false (photo) thì giữ khung cuối. speed: m/s tự nhiên ở tỉ lệ 1
   khi phát đúng fps (0 với idle, photo). Trẻ em: không có bản nón (hat = null). */
import * as THREE from 'three';
import { CONFIG } from '../../config';

export type CrowdClipName = 'walk' | 'jog' | 'idle' | 'photo';
export interface CrowdClip { row: number; frames: number; fps: number; loop: boolean; speed: number }   // row: hàng đầu của đoạn trong texture chuyển động; speed: m/s tự nhiên ở tỉ lệ 1 (0 với idle, photo)
export interface CrowdChar {
  id: string;            // tên Rocketbox
  child: boolean; female: boolean;
  height: number;        // m, ở tỉ lệ 1
  geometry: THREE.BufferGeometry;           // position (Float32 ×3), normal (×3), uv (×2, toạ độ trong atlas), aBones (Uint8 ×2), aW (Float32 ×1: trọng số xương thứ nhất), có index
  hat: THREE.BufferGeometry | null;         // cùng bộ attribute, thêm nón lá; null với trẻ em
  clips: Record<CrowdClipName, CrowdClip>;
}
export interface CrowdParsed { chars: CrowdChar[]; bones: number; animWidth: number; animHeight: number; animData: Uint16Array; maxVerts: number; maxIndices: number }   // animData: RGBA half-float, mỗi hàng một khung, 3 texel mỗi xương
export interface CrowdData extends CrowdParsed { anim: THREE.DataTexture; atlas: THREE.Texture }

const MAGIC = 'DNCR', VERSION = 1;
const CLIP_NAMES: CrowdClipName[] = ['walk', 'jog', 'idle', 'photo'];

/* ===== Đọc tệp (thuần: không DOM, không fetch; chạy được trong node) ===== */
export function crowdParse(buf: ArrayBuffer): CrowdParsed {
  if (buf.byteLength < 12) throw new Error('crowd.bin: tệp quá ngắn');
  const head = new Uint8Array(buf, 0, 4), dv = new DataView(buf);
  if (String.fromCharCode(...head) !== MAGIC) throw new Error('crowd.bin: sai magic');
  const ver = dv.getUint32(4, true); if (ver !== VERSION) throw new Error(`crowd.bin: phiên bản ${ver} (cần ${VERSION})`);
  const J = dv.getUint32(8, true); if (12 + J > buf.byteLength || J % 4) throw new Error('crowd.bin: phần JSON hỏng');
  const meta = JSON.parse(new TextDecoder().decode(new Uint8Array(buf, 12, J)));
  const base = 12 + J;
  const view = <T>(C: { new (b: ArrayBuffer, o: number, n: number): T; BYTES_PER_ELEMENT: number }, off: number, n: number): T => {
    if (off % C.BYTES_PER_ELEMENT || base + off + n * C.BYTES_PER_ELEMENT > buf.byteLength) throw new Error('crowd.bin: mảng vượt tệp');
    return new C(buf, base + off, n);
  };
  const bones: number = meta.bones;
  let maxVerts = 0, maxIndices = 0;
  const chars: CrowdChar[] = meta.chars.map((c) => {
    const nv = c.verts + c.hatVerts, ni = (c.tris + c.hatTris) * 3;
    const pos = view(Float32Array, c.pos, nv * 3), nrm = view(Float32Array, c.nrm, nv * 3), uv = view(Float32Array, c.uv, nv * 2);
    const bi = view(Uint8Array, c.bones, nv * 2), w = view(Float32Array, c.w, nv), idx = view(Uint16Array, c.idx, ni);
    const geo = (v: number, i: number): THREE.BufferGeometry => {
      const g = new THREE.BufferGeometry();
      g.setAttribute('position', new THREE.BufferAttribute(pos.subarray(0, v * 3), 3));
      g.setAttribute('normal', new THREE.BufferAttribute(nrm.subarray(0, v * 3), 3));
      g.setAttribute('uv', new THREE.BufferAttribute(uv.subarray(0, v * 2), 2));
      g.setAttribute('aBones', new THREE.BufferAttribute(bi.subarray(0, v * 2), 2));
      g.setAttribute('aW', new THREE.BufferAttribute(w.subarray(0, v), 1));
      g.setIndex(new THREE.BufferAttribute(idx.subarray(0, i), 1));
      g.computeBoundingBox(); g.computeBoundingSphere();
      maxVerts = Math.max(maxVerts, v); maxIndices = Math.max(maxIndices, i);
      return g;
    };
    const clips = {} as Record<CrowdClipName, CrowdClip>;
    for (const n of CLIP_NAMES) {
      const k = c.clips?.[n]; if (!k) throw new Error(`crowd.bin: ${c.id} thiếu đoạn ${n}`);
      clips[n] = { row: k.row, frames: k.frames, fps: k.fps, loop: !!k.loop, speed: k.speed };
    }
    return { id: c.id, child: !!c.child, female: !!c.female, height: c.height, geometry: geo(c.verts, c.tris * 3), hat: c.hatVerts > 0 ? geo(nv, ni) : null, clips };
  });
  const a = meta.anim;
  if (a.width !== bones * 3 || a.bytes !== a.width * a.height * 8) throw new Error('crowd.bin: kích thước texture chuyển động sai');
  const animData = view(Uint16Array, a.offset, a.width * a.height * 4);
  return { chars, bones, animWidth: a.width, animHeight: a.height, animData, maxVerts, maxIndices };
}

/* ===== Tải trong trình duyệt ===== */
let loaded: CrowdData | null = null;
let pending: Promise<CrowdData | null> | null = null;

// Kết quả của lần crowdLoad đã xong (null nếu chưa xong, lỗi, hoặc ?crowd=off)
export function crowdGet(): CrowdData | null { return loaded; }

// Tải bin + jpg theo BASE_URL, tối đa CONFIG.people.crowd.loadTimeoutMs; lỗi bất kỳ → console.warn một lần, trả null.
// ?crowd=off → null ngay, không gửi yêu cầu nào. Gọi nhiều lần dùng chung một lượt tải.
export function crowdLoad(): Promise<CrowdData | null> {
  if (pending) return pending;
  if (typeof location !== 'undefined' && new URLSearchParams(location.search).get('crowd') === 'off') return (pending = Promise.resolve(null));
  pending = (async () => {
    const C = CONFIG.people.crowd, ctl = new AbortController();
    let timer: ReturnType<typeof setTimeout> | undefined;
    const timeout = new Promise<never>((_, rej) => { timer = setTimeout(() => { ctl.abort(); rej(new Error(`quá ${C.loadTimeoutMs} ms`)); }, C.loadTimeoutMs); });
    const work = (async (): Promise<CrowdData> => {
      const base = import.meta.env.BASE_URL;
      const [rb, ri] = await Promise.all([fetch(base + C.bin, { signal: ctl.signal }), fetch(base + C.atlas, { signal: ctl.signal })]);
      if (!rb.ok || !ri.ok) throw new Error(`HTTP ${rb.status} / ${ri.status}`);
      const [buf, blob] = await Promise.all([rb.arrayBuffer(), ri.blob()]);
      const parsed = crowdParse(buf);
      const bmp = await createImageBitmap(blob);
      const atlas = new THREE.Texture(bmp);
      atlas.flipY = false; atlas.colorSpace = THREE.SRGBColorSpace; atlas.name = 'peopleCrowdAtlas'; atlas.needsUpdate = true;
      const anim = new THREE.DataTexture(parsed.animData as Uint16Array<ArrayBuffer>, parsed.animWidth, parsed.animHeight, THREE.RGBAFormat, THREE.HalfFloatType);
      anim.minFilter = anim.magFilter = THREE.NearestFilter; anim.generateMipmaps = false; anim.name = 'peopleCrowdAnim'; anim.needsUpdate = true;
      return { ...parsed, anim, atlas };
    })();
    work.catch(() => {}); timeout.catch(() => {});
    try {
      loaded = await Promise.race([work, timeout]);
    } catch (e) {
      console.warn('[people] không dùng được đám đông người thật, dùng hình khối:', e instanceof Error ? e.message : e);
      loaded = null;
    } finally { clearTimeout(timer); }
    return loaded;
  })();
  return pending;
}
import * as THREE from 'three';
import { CONFIG } from '../../config';
import { shared } from '../../core/shared';
import { PP_FLAG } from './kinds';
import type { CrowdData, CrowdClip, CrowdClipName } from './crowdData';
import type { Walker } from '../people';

/* =====================================================================
   ĐÁM ĐÔNG NGƯỜI THẬT (D-032) — mỗi hệ người đi bộ một THREE.BatchedMesh (r165, WEBGL_multi_draw ⇒ 1 lệnh vẽ), một id mỗi người.
   Spec: docs/superpowers/specs/2026-11-12-dam-dong-nguoi-that-design.md §4, §5. Dữ liệu: crowdData.ts (định dạng crowd.bin ở đầu file đó).
   - Skin trong vertex shader: 2 xương mỗi đỉnh (aBones, aW), ma trận 3×4 của xương đọc từ texture chuyển động (uCrowdAnim, texelFetch),
     nội suy hai khung liền nhau; đoạn lặp thì khung cuối nội suy về khung đầu, đoạn không lặp (photo) giữ khung cuối.
   - Thông số từng người (hàng đầu đoạn, ±số khung, khung/giây, pha theo khung) nằm trong một DataTexture float dùng chung cho cả 3 hệ
     (uCrowdPeople). Chỉ số của người trong texture đó (= chỗ bắt đầu của hệ + id) ghi vào kênh alpha của batchingColorTexture
     (setColorAt chỉ ghi rgb; rgb = hệ số sáng theo người, spec §4.11). Một vật liệu cho cả 3 hệ ⇒ không có uniform riêng theo hệ.
   - Thời gian: shared.uTime; lấy mod theo chu kỳ của người TRƯỚC khi nhân khung/giây để pha không mất chính xác khi trang chạy lâu.
   - Phải setColorAt cho mọi id (r165: thiếu bảng màu thì renderer tra lại program mỗi khung). sortObjects = false; không setInstanceCountAt.
   - Ẩn người: setVisibleAt (tự đặt _visibilityChanged). setMatrixAt tự đặt matricesTexture.needsUpdate.
   - Khối cầu bao từng id: của lưới nguồn, nới cullPad / tỉ lệ người (đơn vị cục bộ; matrix nhân lại tỉ lệ) để tay chân không bị cắt nhầm.
   ===================================================================== */
const PEOPLE_W = 32, PEOPLE_H = 32;   // texel — sức chứa texture thông số: 1 024 người cho mọi hệ (hiện 226)

/* ---------- băm theo chỉ số (không dùng rand / rnd / rng) ---------- */
const crHashStr = (s: string): number => { let h = 2166136261; for (let k = 0; k < s.length; k++) h = Math.imul(h ^ s.charCodeAt(k), 16777619); return h >>> 0; };
const crHash = (a: number, b: number): number => {
  let h = Math.imul(a ^ Math.imul((b + 0x9e3779b9) | 0, 0x85ebca6b), 0xc2b2ae35);
  h ^= h >>> 16; h = Math.imul(h, 0x7feb352d); h ^= h >>> 15; h = Math.imul(h, 0x846ca68b); h ^= h >>> 16;
  return (h >>> 0) / 4294967296;
};

/* Dùng được người thật không: có dữ liệu và có WEBGL_multi_draw (thiếu thì r165 vẽ mỗi người một lệnh ⇒ lùi về hình khối) */
export function crowdUsable(data: CrowdData | null, hasMultiDraw: boolean): boolean {
  return !!data && hasMultiDraw && data.chars.some((c) => c.child) && data.chars.some((c) => !c.child);
}

/* Chọn nhân vật cho người i của hệ system (tất định). isChild → chỉ nhân vật trẻ em; avoid: nhân vật của người đi cùng (−1 nếu không), tránh trùng khi có ≥ 2 lựa chọn */
export function crowdPick(chars: { child: boolean }[], system: string, i: number, isChild: boolean, avoid: number): number {
  let cand: number[] = [];
  chars.forEach((c, k) => { if (c.child === isChild) cand.push(k); });
  if (!cand.length) cand = chars.map((_, k) => k);
  let k = Math.floor(crHash(crHashStr(system), i) * cand.length);
  if (cand[k] === avoid && cand.length > 1) k = (k + 1) % cand.length;
  return cand[k];
}

/* Nhịp phát chuyển động = tốc độ người ÷ (tốc độ tự nhiên của đoạn × tỉ lệ người), kẹp [rateMin, rateMax] (spec §4.5). natural = 0 (đứng) → 1 */
export function crowdRate(speed: number, natural: number, scale: number): number {
  const C = CONFIG.people.crowd;
  if (!(natural > 0)) return 1;
  return Math.min(C.rateMax, Math.max(C.rateMin, speed / (natural * scale)));
}

/* Khung (số thực) trong [0, frames) tại thời điểm t (s); phase: pha chu kỳ, rad (Walker.phase). Bản CPU của công thức trong shader (VS_SKIN) */
export function crowdFrame(t: number, clip: CrowdClip, rate: number, phase: number): number {
  const N = clip.frames;
  if (!clip.loop) return N - 1;
  const fr = clip.fps * rate, T = N / fr, ph = crPhase(phase, N);
  const f = ((t % T) * fr + ph) % N;
  return f < 0 ? f + N : f;
}
const crPhase = (phase: number, N: number) => ((((phase / (2 * Math.PI)) % 1) + 1) % 1) * N;   // rad → khung, [0, N)
const crClip = (w: Walker): CrowdClipName => (w.kind === 'run' ? 'jog' : w.kind === 'stand' ? ((w.flags ?? 0) & PP_FLAG.photo ? 'photo' : 'idle') : 'walk');

/* ---------- shader ---------- */
const VS_PARS = /* glsl */`#include <batching_pars_vertex>
uniform highp sampler2D uCrowdAnim;
uniform highp sampler2D uCrowdPeople;
uniform float uTime;
attribute vec2 aBones;
attribute float aW;
vec4 crRow( int c, int f0, int f1, float t ) { return mix( texelFetch( uCrowdAnim, ivec2( c, f0 ), 0 ), texelFetch( uCrowdAnim, ivec2( c, f1 ), 0 ), t ); }
`;
// thay beginnormal_vertex: tính 3 hàng ma trận skin (crR0..2) một lần, dùng lại ở begin_vertex
const VS_SKIN = /* glsl */`
vec4 crR0 = vec4( 1.0, 0.0, 0.0, 0.0 ), crR1 = vec4( 0.0, 1.0, 0.0, 0.0 ), crR2 = vec4( 0.0, 0.0, 1.0, 0.0 );
#if defined( USE_BATCHING ) && defined( USE_BATCHING_COLOR )
{
  int crCs = textureSize( batchingColorTexture, 0 ).x, crId = int( batchId );
  int crG = int( texelFetch( batchingColorTexture, ivec2( crId % crCs, crId / crCs ), 0 ).a + 0.5 );   // chỉ số người trong uCrowdPeople
  int crPw = textureSize( uCrowdPeople, 0 ).x;
  vec4 crP = texelFetch( uCrowdPeople, ivec2( crG % crPw, crG / crPw ), 0 );   // x hàng đầu đoạn, y ±số khung (âm: giữ khung cuối), z khung/giây, w pha (khung)
  int crN = int( abs( crP.y ) + 0.5 ), f0 = crN - 1, f1 = crN - 1; float ft = 0.0;
  if ( crP.y > 0.0 ) {
    float crF = mod( mod( uTime, crP.y / crP.z ) * crP.z + crP.w, crP.y );   // mod theo chu kỳ trước: uTime lớn không làm mất chính xác pha
    f0 = min( int( crF ), crN - 1 ); f1 = f0 + 1 >= crN ? 0 : f0 + 1; ft = fract( crF );
  }
  int crRw = int( crP.x + 0.5 ); f0 += crRw; f1 += crRw;
  int b0 = int( aBones.x + 0.5 ) * 3, b1 = int( aBones.y + 0.5 ) * 3; float w1 = 1.0 - aW;
  crR0 = crRow( b0, f0, f1, ft ) * aW + crRow( b1, f0, f1, ft ) * w1;
  crR1 = crRow( b0 + 1, f0, f1, ft ) * aW + crRow( b1 + 1, f0, f1, ft ) * w1;
  crR2 = crRow( b0 + 2, f0, f1, ft ) * aW + crRow( b1 + 2, f0, f1, ft ) * w1;
}
#endif
vec3 objectNormal = vec3( dot( crR0.xyz, normal ), dot( crR1.xyz, normal ), dot( crR2.xyz, normal ) );
#ifdef USE_TANGENT
vec3 objectTangent = vec3( tangent.xyz );
#endif
`;
const VS_POS = /* glsl */`vec4 crPos = vec4( position, 1.0 );
vec3 transformed = vec3( dot( crR0, crPos ), dot( crR1, crPos ), dot( crR2, crPos ) );
#ifdef USE_ALPHAHASH
vPosition = vec3( position );
#endif
`;

type CrowdState = { people: THREE.DataTexture; next: number };
const mats = new WeakMap<CrowdData, THREE.MeshStandardMaterial>();
/* Một vật liệu dùng chung cho 3 hệ (theo bộ dữ liệu). Texture trong uniform (uCrowdAnim, uCrowdPeople) không được prewarm tải trước:
   bên dựng gọi renderer.initTexture (people.ts) */
export function crowdMaterial(data: CrowdData): THREE.MeshStandardMaterial {
  const old = mats.get(data); if (old) return old;
  const m = new THREE.MeshStandardMaterial({ map: data.atlas, roughness: CONFIG.people.roughness, metalness: 0 });
  m.name = 'peopleCrowd';
  const people = new THREE.DataTexture(new Float32Array(PEOPLE_W * PEOPLE_H * 4), PEOPLE_W, PEOPLE_H, THREE.RGBAFormat, THREE.FloatType);
  people.minFilter = people.magFilter = THREE.NearestFilter; people.generateMipmaps = false; people.name = 'peopleCrowdParams'; people.needsUpdate = true;
  const state: CrowdState = { people, next: 0 };
  m.userData.crowd = state;
  m.onBeforeCompile = (s) => {
    s.uniforms.uTime = shared.uTime; s.uniforms.uCrowdAnim = { value: data.anim }; s.uniforms.uCrowdPeople = { value: people };
    s.vertexShader = s.vertexShader.replace('#include <batching_pars_vertex>', VS_PARS).replace('#include <beginnormal_vertex>', VS_SKIN).replace('#include <begin_vertex>', VS_POS);
    m.userData.vs = s.vertexShader;
