// Điều tra ảnh đen people-cau-song-han-dem.png: mở bản build, đêm, camera theo người Cầu sông Hàn như people-check, chụp; so với ?crowd=off
import { serveDir, launch, openApp, frames } from 'file:///D:/2026%20-%20Tuan/danang-vite/tests/lib.mjs';
const OUT = 'C:/Users/Client/AppData/Local/Temp/claude/e6d5994f4eac8fdb/3eef7d66-e5c7-4026-a230-4887df104ab6/scratchpad/';
const srv = await serveDir('D:/2026 - Tuan/danang-vite/dist/');
const browser = await launch();
for (const q of (process.argv[2] ?? ',?crowd=off').split(',')) {
  const { page, errors } = await openApp(browser, srv.url + q, { width: 960, height: 540 });
  const setNight = async (v) => { await page.evaluate((v) => { window.__app.dayNight.target = v; window.__app.dayNight.night = v; }, v); await frames(page, 3); };
  const info = (i, off) => page.evaluate(([i, off]) => {
    const a = window.__app, T = a.THREE, m = a.scene.getObjectByName('sh-people').children.find((o) => o.isInstancedMesh || o.isBatchedMesh), M = new T.Matrix4(), P = new T.Vector3();
    m.updateWorldMatrix(true, false); m.getMatrixAt(i, M); M.premultiply(m.matrixWorld); P.setFromMatrixPosition(M);
    a.camera.position.set(P.x + off[0], P.y + off[1], P.z + off[2]); a.controls.target.set(P.x, P.y + 1, P.z); a.controls.update();
    return { P: P.toArray(), cam: a.camera.position.toArray(), grp: m.parent.visible };
  }, [i, off]);
  const ps = await page.evaluate(() => window.__app.people.positions('sh-people'));
  const sWalk = ps.find((p) => p.i < 36 && p.kind !== 'stand')?.i ?? 0;
  for (const night of [0, 1]) {
    await setNight(night);
    const r = await info(sWalk, [7, 3, -8]); await frames(page, 3);
    const calls = await page.evaluate(() => window.__app.renderer.info.render.calls);
    await page.screenshot({ path: `${OUT}sh-${q ? 'off' : 'real'}-${night}.png` });
    console.log(q || 'real', 'night', night, JSON.stringify(r), 'calls', calls);
  }
  console.log('errors', errors);
  await page.close();
}
await browser.close(); srv.close();

